// Bundles @ffmpeg/ffmpeg's ESM worker (worker.js + its two tiny deps) into a
// single self-contained module at public/ffmpeg-worker.js.
//
// Why self-host: FFmpeg.load() always spawns the class worker with
// { type: "module" }. The UMD dist worker (814.ffmpeg.js) is webpack-compiled,
// so its dynamic `import(coreURL)` fallback becomes __webpack_require__ and
// dies with "Cannot find module blob:...". The ESM dist worker works, but it
// has relative imports (./const.js, ./errors.js) that cannot resolve from a
// blob: URL — so we inline them and serve the result same-origin.
//
// Run after upgrading @ffmpeg/ffmpeg:  node scripts/bundle-ffmpeg-worker.mjs
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const esm = path.join(root, "node_modules", "@ffmpeg", "ffmpeg", "dist", "esm");
const version = JSON.parse(
  fs.readFileSync(path.join(root, "node_modules", "@ffmpeg", "ffmpeg", "package.json"), "utf8")
).version;

const strip = (src) =>
  src
    .replace(/^import .*$/gm, "")
    .replace(/^export /gm, "")
    .replace(/^\/\/\/ <reference.*$/gm, "");

const out = [
  `// AUTO-GENERATED by scripts/bundle-ffmpeg-worker.mjs — do not edit by hand.`,
  `// Source: @ffmpeg/ffmpeg@${version} dist/esm/{const,errors,worker}.js (MIT).`,
  strip(fs.readFileSync(path.join(esm, "const.js"), "utf8")),
  strip(fs.readFileSync(path.join(esm, "errors.js"), "utf8")),
  strip(fs.readFileSync(path.join(esm, "worker.js"), "utf8")),
].join("\n");

const dest = path.join(root, "public", "ffmpeg-worker.js");
fs.writeFileSync(dest, out);
console.log("wrote", dest, fs.statSync(dest).size, "bytes (from @ffmpeg/ffmpeg", version + ")");
